   1 | void
   2 | smb2_parse_contexts(struct TCP_Server_Info *server,
   3 | 		    struct smb2_create_rsp *rsp,
   4 | 		    unsigned int *epoch, char *lease_key, __u8 *oplock,
   5 | 		    struct smb2_file_all_info *buf,
   6 | 		    struct create_posix_rsp *posix)
   7 | {
   8 | 	char *data_offset;
   9 | 	struct create_context *cc;
  10 | 	unsigned int next;
  11 | 	unsigned int remaining;
  12 | 	char *name;
  13 | 	static const char smb3_create_tag_posix[] = {
  14 | 		0x93, 0xAD, 0x25, 0x50, 0x9C,
  15 | 		0xB4, 0x11, 0xE7, 0xB4, 0x23, 0x83,
  16 | 		0xDE, 0x96, 0x8B, 0xCD, 0x7C
  17 | 	};
  18 | 
  19 | 	*oplock = 0;
  20 | 	data_offset = (char *)rsp + le32_to_cpu(rsp->CreateContextsOffset);
  21 | 	remaining = le32_to_cpu(rsp->CreateContextsLength);
  22 | 	cc = (struct create_context *)data_offset;
  23 | 
  24 | 	/* Initialize inode number to 0 in case no valid data in qfid context */
  25 | 	if (buf)
  26 | 		buf->IndexNumber = 0;
  27 | 
  28 | 	while (remaining >= sizeof(struct create_context)) {
  29 | 		name = le16_to_cpu(cc->NameOffset) + (char *)cc;
  30 | 		if (le16_to_cpu(cc->NameLength) == 4 &&
  31 | 		    strncmp(name, SMB2_CREATE_REQUEST_LEASE, 4) == 0)
  32 | 			*oplock = server->ops->parse_lease_buf(cc, epoch,
  33 | 							   lease_key);
  34 | 		else if (buf && (le16_to_cpu(cc->NameLength) == 4) &&
  35 | 		    strncmp(name, SMB2_CREATE_QUERY_ON_DISK_ID, 4) == 0)
  36 | 			parse_query_id_ctxt(cc, buf);
  37 | 		else if ((le16_to_cpu(cc->NameLength) == 16)) {
  38 | 			if (posix &&
  39 | 			    memcmp(name, smb3_create_tag_posix, 16) == 0)
  40 | 				parse_posix_ctxt(cc, buf, posix);
  41 | 		}
  42 | 		/* else {
  43 | 			cifs_dbg(FYI, "Context not matched with len %d\n",
  44 | 				le16_to_cpu(cc->NameLength));
  45 | 			cifs_dump_mem("Cctxt name: ", name, 4);
  46 | 		} */
  47 | 
  48 | 		next = le32_to_cpu(cc->Next);
  49 | 		if (!next)
  50 | 			break;
  51 | 		remaining -= next;
  52 | 		cc = (struct create_context *)((char *)cc + next);
  53 | 	}
  54 | 
  55 | 	if (rsp->OplockLevel != SMB2_OPLOCK_LEVEL_LEASE)
  56 | 		*oplock = rsp->OplockLevel;
  57 | 
  58 | 	return;
  59 | }
  60 | 
</FUNCTION_SOURCE>
<CLAIM evidence_lines="20, 21, 28, 29, 48, 51, 52">
mechanism: The function trusts attacker-controlled CreateContextsOffset/CreateContextsLength and per-context Next/NameOffset fields without validating them against the response buffer bounds: data_offset (line 20) is computed from an unchecked offset, and the loop advances cc by the unchecked Next value (lines 48-52) while remaining is only decremented by next without checking next <= remaining, so a crafted Next or NameOffset can make cc/name point outside the buffer, causing out-of-bounds reads in strncmp/memcmp and the parse_* helpers.
</CLAIM>

