   1 | static ssize_t usbip_sockfd_store(struct device *dev, struct device_attribute *attr,
   2 | 			    const char *buf, size_t count)
   3 | {
   4 | 	struct stub_device *sdev = dev_get_drvdata(dev);
   5 | 	int sockfd = 0;
   6 | 	struct socket *socket;
   7 | 	int rv;
   8 | 
   9 | 	if (!sdev) {
  10 | 		dev_err(dev, "sdev is null\n");
  11 | 		return -ENODEV;
  12 | 	}
  13 | 
  14 | 	rv = sscanf(buf, "%d", &sockfd);
  15 | 	if (rv != 1)
  16 | 		return -EINVAL;
  17 | 
  18 | 	if (sockfd != -1) {
  19 | 		int err;
  20 | 
  21 | 		dev_info(dev, "stub up\n");
  22 | 
  23 | 		spin_lock_irq(&sdev->ud.lock);
  24 | 
  25 | 		if (sdev->ud.status != SDEV_ST_AVAILABLE) {
  26 | 			dev_err(dev, "not ready\n");
  27 | 			goto err;
  28 | 		}
  29 | 
  30 | 		socket = sockfd_lookup(sockfd, &err);
  31 | 		if (!socket) {
  32 | 			dev_err(dev, "failed to lookup sock");
  33 | 			goto err;
  34 | 		}
  35 | 
  36 | 		if (socket->type != SOCK_STREAM) {
  37 | 			dev_err(dev, "Expecting SOCK_STREAM - found %d",
  38 | 				socket->type);
  39 | 			goto sock_err;
  40 | 		}
  41 | 
  42 | 		sdev->ud.tcp_socket = socket;
  43 | 		sdev->ud.sockfd = sockfd;
  44 | 
  45 | 		spin_unlock_irq(&sdev->ud.lock);
  46 | 
  47 | 		sdev->ud.tcp_rx = kthread_get_run(stub_rx_loop, &sdev->ud,
  48 | 						  "stub_rx");
  49 | 		sdev->ud.tcp_tx = kthread_get_run(stub_tx_loop, &sdev->ud,
  50 | 						  "stub_tx");
  51 | 
  52 | 		spin_lock_irq(&sdev->ud.lock);
  53 | 		sdev->ud.status = SDEV_ST_USED;
  54 | 		spin_unlock_irq(&sdev->ud.lock);
  55 | 
  56 | 	} else {
  57 | 		dev_info(dev, "stub down\n");
  58 | 
  59 | 		spin_lock_irq(&sdev->ud.lock);
  60 | 		if (sdev->ud.status != SDEV_ST_USED)
  61 | 			goto err;
  62 | 
  63 | 		spin_unlock_irq(&sdev->ud.lock);
  64 | 
  65 | 		usbip_event_add(&sdev->ud, SDEV_EVENT_DOWN);
  66 | 	}
  67 | 
  68 | 	return count;
  69 | 
  70 | sock_err:
  71 | 	sockfd_put(socket);
  72 | err:
  73 | 	spin_unlock_irq(&sdev->ud.lock);
  74 | 	return -EINVAL;
  75 | }
  76 | 
</FUNCTION_SOURCE>
<CLAIM evidence_lines="30, 42, 43, 47, 49, 52, 53">
mechanism: After sockfd_lookup succeeds at line 30, the socket reference is stored into sdev->ud.tcp_socket (line 42) and the lock is released (line 45), but if kthread_get_run fails (lines 47-50) the code still proceeds to set status to SDEV_ST_USED (line 53) without checking for NULL thread pointers or releasing the socket reference, leaving a dangling/leaked socket and a device marked as used with no worker threads; additionally the sockfd from sscanf (line 14) is attacker-controlled and passed directly to sockfd_lookup (line 30) without validating it is a valid descriptor, though sockfd_lookup itself handles that safely.
</CLAIM>

